-- Seed main en translations from apps/main/src/lib/locales/en.json
INSERT INTO translations (tenant_id, locale, "key", value) VALUES
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.mission_heading', 'Our Mission'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.mission_text', 'JapaConnect is built to serve the Nigerian diaspora and Nigerians planning to relocate abroad. We provide community, resources, and expert guidance to make your journey smoother.'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.mission_text_1', 'JapaConnect is a community platform built for the Nigerian diaspora and Nigerians planning to relocate abroad. We provide tools for sharing experiences, finding resources, and building meaningful connections across borders.'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.mission_text_2', 'Our mission is to make the relocation journey less isolating by connecting people with shared experiences, reliable information, and supportive communities.'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.mission_title', 'Our Mission'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.offer_1', 'Community spaces organized by country, profession, and interest'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.offer_2', 'A rich content editor for sharing guides, stories, and resources'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.offer_3', 'University discovery and comparison tools'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.offer_4', 'Real-time notifications and messaging'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.offer_5', 'Curated immigration and relocation information'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.offer_community', 'Community spaces for every destination and topic'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.offer_forum', 'Q&A forum with verified answers from experienced migrants'),
    ('00000000-0000-0000-0000-000000000001', 'en', 'about.offer_heading', 'What We Offer'),
