INSERT INTO translations (tenant_id, locale, "key", value) VALUES
    ('00000000-0000-0000-0000-000000000001', 'fr', 'about.mission_heading', 'Notre mission'),
    ('00000000-0000-0000-0000-000000000001', 'fr', 'about.mission_text', 'JapaConnect a été conçu pour servir la diaspora nigériane et les Nigérians préparant leur expatriation. Nous offrons une communauté, des ressources et des conseils d''experts pour faciliter votre parcours.'),
    ('00000000-0000-0000-0000-000000000001', 'fr', 'about.mission_text_1', 'JapaConnect est une plateforme communautaire créée pour la diaspora nigériane et les Nigérians préparant leur expatriation. Nous fournissons des outils pour partager des expériences, trouver des ressources et créer des connexions significatives à travers les frontières.'),
    ('00000000-0000-0000-0000-000000000001', 'fr', 'about.mission_text_2', 'Notre mission est de rendre le parcours d''expatriation moins isolant en connectant les personnes ayant des expériences partagées, des informations fiables et des communautés de soutien.'),
    ('00000000-0000-0000-0000-000000000001', 'fr', 'about.mission_title', 'Notre mission'),
    ('00000000-0000-0000-0000-000000000001', 'fr', 'about.offer_1', 'Des espaces communautaires organisés par pays, profession et intérêt'),
    ('00000000-0000-0000-0000-000000000001', 'fr', 'about.offer_2', 'Un éditeur de contenu riche pour partager des guides, des histoires et des ressources'),
    ('00000000-0000-0000-0000-000000000001', 'fr', 'about.offer_3', 'Des outils de découverte et de comparaison d''universités'),
